    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # A complete stripe identifies the color used to extend a partial stripe.
    stripe_colors = {row[0] for row in grid if all(x == row[0] for x in row)}
    for r, row in enumerate(grid):
        for color in stripe_colors:
            if color != bg and color in row and all(x in (bg, color) for x in row):
                for c in range(w):
                    if row[c] == bg:
                        out[r][c] = 1

